# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Use a safety-gated, hysteretic controller with brief target verification,
    bounded reacquisition scanning, and direct corridor-aware approach steering.
    """
    memory = dict(memory or {})
    state = memory.get("state", "IDLE")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")
    previous_action = memory.get("previous_action", "STOP")

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_confidence = float(observation["target_confidence"])
    identity_confidence = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_confidence = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])
    heading_error = float(observation["heading_error"])

    def finish(action, confidence, next_state):
        memory["state"] = next_state
        memory["previous_action"] = action
        return action, confidence, memory

    if safety_confidence < 0.60 or closing_risk >= 0.75:
        return finish("STOP", 0.99, "STOPPED")

    confirmed = (
        visible
        and target_confidence >= 0.55
        and identity_confidence >= 0.60
    )
    if not confirmed:
        if state in {"LOCKED", "APPROACH", "REACQUIRE"} or lost_steps > 0:
            if lost_steps <= 1:
                return finish("STOP", 0.92, "REACQUIRE")
            action = scan_direction
            memory["scan_direction"] = (
                "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
            )
            return finish(action, 0.75, "SEARCH")
        return finish(scan_direction, 0.75, "SEARCH")

    if track_age < 2:
        return finish("SLOW_DOWN", 0.80, "VERIFY")

    if distance == "near":
        if abs(heading_error) <= 15.0 and identity_confidence >= 0.80:
            return finish("ARRIVED", 0.96, "ARRIVED")
        turn_error = bearing if abs(bearing) > 3.0 else heading_error
        return finish(
            "VEER_LEFT" if turn_error < 0 else "VEER_RIGHT",
            0.88,
            "APPROACH",
        )

    if bearing < -12.0 and observation["corridor_left"]:
        return finish("VEER_LEFT", 0.90, "APPROACH")
    if bearing > 12.0 and observation["corridor_right"]:
        return finish("VEER_RIGHT", 0.90, "APPROACH")

    if observation["corridor_center"] and abs(bearing) <= 12.0:
        return finish("FORWARD", 0.90, "APPROACH")

    if observation["corridor_left"] and not observation["corridor_right"]:
        return finish("VEER_LEFT", 0.82, "APPROACH")
    if observation["corridor_right"] and not observation["corridor_left"]:
        return finish("VEER_RIGHT", 0.82, "APPROACH")

    if previous_action in {"VEER_LEFT", "VEER_RIGHT"}:
        return finish(previous_action, 0.70, "APPROACH")
    return finish("STOP", 0.98, "STOPPED")
# EVOLVE-BLOCK-END
